// Generated by vibelang from src/features/presence/view.ts; the migrate flow writes it again with each batch.
// What the branch header shows of the room (docs/features/branch-workspace.md#presence): everyone on the branch, this
// person first, once each however many tabs they have open, with where they are; and where following one of them goes.
// Pure, so the avatars' React view only renders it.
/** Where a place is, in the fewest words: the file or folder's path, or Terminal. */
export const placeOf = (where) => where === null ? undefined : where.view === "terminal" ? "Terminal" : where.path === "" ? "Code" : where.path;
/**
 * Everyone in the room once each: this person first, by this tab, titled `<name> (you)`, so the header shows who is
 * there even alone; then everyone else in the room's order, by their latest tab, each titled with where they are.
 */
export const avatarsOf = (participants) => {
    const me = participants.find((participant) => participant.self);
    const latest = new Map();
    for (const participant of participants) {
        if (participant.principal !== me?.principal)
            latest.set(participant.principal, participant);
    }
    const others = [...latest.values()].map((participant) => {
        const place = placeOf(participant.where);
        return { id: participant.id, name: participant.name, title: place === undefined ? participant.name : `${participant.name} · ${place}` };
    });
    return me === undefined ? others : [{ id: me.id, name: me.name, title: `${me.name} (you)` }, ...others];
};
/**
 * Where following the person on connection `id` goes on the branch's page: their path; the file they edit, beside its
 * directory; or, in the Terminal view, the terminal they watch (`me` when theirs is unnamed). `undefined` when they are
 * gone or nowhere yet.
 */
export const followOf = (participants, id) => {
    const where = participants.find((participant) => participant.id === id)?.where ?? null;
    if (where === null)
        return undefined;
    if (where.view === "code")
        return { path: where.path };
    if (where.view === "edit")
        return { path: where.path.split("/").slice(0, -1).join("/"), edit: where.path };
    return { path: "", terminal: where.terminalId ?? "me" };
};
/** What this person may do now, as the room last said: `write` or `read`, `undefined` until the room says. */
export const selfAccessOf = (participants) => participants.find((participant) => participant.self)?.access;
